#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/wait.h>
#include <unistd.h>

static void fail(const char *what) {
    perror(what);
    exit(1);
}

int main(void) {
    /* ---- pipe: 父子进程间字节流 ---- */
    int pipefd[2];
    if (pipe(pipefd) == -1) fail("pipe");

    /* ---- POSIX shared memory: 同一物理页映射 ---- */
    char shm_name[64];
    snprintf(shm_name, sizeof(shm_name), "/ipc_demo_%ld", (long)getpid());
    int shmfd = shm_open(shm_name, O_CREAT | O_EXCL | O_RDWR, 0600);
    if (shmfd == -1) fail("shm_open");
    if (ftruncate(shmfd, 4096) == -1) fail("ftruncate");
    char *shared = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, shmfd, 0);
    if (shared == MAP_FAILED) fail("mmap");
    snprintf(shared, 4096, "parent initialized shared page");

    pid_t pid = fork();
    if (pid == -1) fail("fork");

    if (pid == 0) {
        /* 子进程写 pipe: 只是写入字节流，无消息边界 */
        close(pipefd[0]);
        const char *msg = "child wrote bytes via pipe";
        if (write(pipefd[1], msg, strlen(msg)) == -1) fail("write");
        close(pipefd[1]);

        /* 子进程直接改 shared 映射区; 父进程稍后能看到同一物理页的新内容
         * 这里是单写者演示，真实工程必须加同步 */
        snprintf(shared, 4096, "child updated the same mapped page");

        munmap(shared, 4096);
        close(shmfd);
        return 0;
    }

    /* 父进程读 pipe: 读到的是字节流片段，需手动补 '\0' */
    close(pipefd[1]);
    char pipe_buf[128];
    ssize_t n = read(pipefd[0], pipe_buf, sizeof(pipe_buf) - 1);
    if (n == -1) fail("read");
    pipe_buf[n] = '\0';

    /* 等子进程结束后读 shared 内容（同一页映射） */
    if (waitpid(pid, NULL, 0) == -1) fail("waitpid");
    printf("pipe got: %s\n", pipe_buf);
    printf("shm got:  %s\n", shared);

    close(pipefd[0]);
    munmap(shared, 4096);
    close(shmfd);
    shm_unlink(shm_name);  /* 清理命名共享内存对象，避免残留 */
    return 0;
}
